head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > getInstanceValue]<br/>Instance 내부에서 XPath 에 해당하는 노드의 텍스트 값(nodeValue) 을 반환합니다.",
    "validation" : [
        "xpath(필수) 파라미터로 값을 가져올 Instance 노드의 XPath 경로를 설정할 수 있어야 합니다.",
        "xpath 로 찾은 노드의 텍스트 값을 반환해야 합니다.",
        "노드를 찾지 못하면 빈 문자열('') 을 반환해야 합니다.",
        "노드가 Element 타입이면 모든 자식 텍스트 노드와 CDATA 노드의 값을 연결하여 반환해야 합니다.",
        "노드가 Attribute 타입이면 nodeValue 를 직접 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getInstanceValue_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : Element 타입 노드 값 조회 (가이드 예제)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : Element 노드 값 조회 (bookstore/book/title) ──");

        var value = WebSquare.ModelUtil.getInstanceValue("bookstore/book/title");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof value) + " / 반환값 : '" + value + "'");
    } else if (scenario === "2") {
        // 시나리오 2 : Attribute 타입 노드 값 조회 (가이드 예제)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : Attribute 노드 값 조회 (bookstore/book/title/@lang) ──");

        var value = WebSquare.ModelUtil.getInstanceValue("bookstore/book/title/@lang");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof value) + " / 반환값 : '" + value + "'");
    } else if (scenario === "3") {
        // 시나리오 3 : Element 자식 텍스트 + CDATA 연결 반환 (@spec)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 자식 텍스트+CDATA 연결 (bookstore/book[1]/description) ──");

        var value = WebSquare.ModelUtil.getInstanceValue("bookstore/book[1]/description");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof value) + " / 반환값 : '" + value + "'");        
    } else if (scenario === "4") {
        // 시나리오 4 : 존재하지 않는 xpath → "" 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : 존재하지 않는 xpath (bookstore/notExist) ──");

        var value = WebSquare.ModelUtil.getInstanceValue("bookstore/notExist");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof value) + " / 반환값 : '" + value + "' (길이 : " + value.length + ")");
    }
};
